// ***************
// Filename: feature_detect_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of feature_detect: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to feature_detect's logic on named ports,
//   its status comes back on input ports. Edge and motion features of a video
//   stream for object detectors: Sobel edges and a background of cells
//   (lowest / highest luma) with the camera shift from luma profiles, two
//   bits per pixel. Generated by ip/scripts/regmap_gen.py from
//   feature_detect_regs.json: edit the JSON and regenerate (the IP_VERSION /
//   IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "FEAT" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x18 CTRL        RW   control, reset 0x0
//                       [0] EN: enable (follow the stream)
//                       [1] EDGE_EN: edge bit on
//                       [2] MOTION_EN: motion bit on
//                       [3] AUTO_SHIFT: use the searched camera shift (else
//                         SHIFT)
//                       [4] RESTART: write 1: background, profiles and shift
//                         start again (the next frame fills the background)
//     0x1C FRAME_SIZE  RW   frame size, reset 0x0
//                       [15:0] WIDTH: width
//                       [31:16] HEIGHT: height
//     0x20 EDGE        RW   edge detector, reset 0x80080
//                       [10:0] THRESH: Sobel |Gx| + |Gy| above this: an edge
//                       [19:16] SPAN: an edge in the last SPAN pixels of the
//                         line sets the bit (0 or 1: the pixel only)
//     0x24 MOTION      RW   motion detector, reset 0x2214
//                       [7:0] THRESH: luma beyond the background cell's range
//                         by more than this: moving
//                       [11:8] SPAN: fill along the line, as EDGE.SPAN
//                       [14:12] RATE: background moves 1 / 2^RATE of the way
//                         to each frame
//     0x28 SHIFT       RW   camera shift used without AUTO_SHIFT (cells,
//                       taken at the frame start), reset 0x0
//                       [7:0] X: columns (signed): content moved right
//                       [15:8] Y: lines (signed): content moved down
//     0x2C SHIFT_EST   RO   camera shift found by the last search (cells)
//                       [7:0] X: columns (signed)
//                       [15:8] Y: lines (signed)
//     0x30 STATUS      RO   state
//                       [0] IN_FRAME: in a frame
//                       [1] BG_VALID: background valid (motion detected)
//                       [2] BUSY: shift search running
//                       [31:16] FRAMES: FRAMES[15:0]
//     0x34 FRAMES      RO   frames seen
//     0x38 EDGE_COUNT  RO   pixels with the edge bit in the last frame
//     0x3C MOTION_COUNT RO   pixels with the motion bit in the last frame
//     0x40 SHIFT_USED  RO   camera shift in effect for the current / last
//                       frame (cells)
//                       [7:0] X: columns (signed)
//                       [15:8] Y: lines (signed)
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - clk. Reset
//   - synchronous active low rst_n. Latency - 2 clocks per write and read.
// Date: 2026-10-16
module feature_detect_regs (
  input  logic          clk,             // clock
  input  logic          rst_n,           // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // r: feature_detect_regs_if.regs (src/include/feature_detect_regs_if.sv) {ctrl_o=cfg_ctrl ctrl_wr_o=cfg_ctrl_wr frame_size_o=cfg_frame_size frame_size_wr_o=cfg_frame_size_wr edge_o=cfg_edge edge_wr_o=cfg_edge_wr motion_o=cfg_motion motion_wr_o=cfg_motion_wr shift_o=cfg_shift shift_wr_o=cfg_shift_wr shift_est_i=sts_shift_est status_i=sts_status frames_i=sts_frames edge_count_i=sts_edge_count motion_count_i=sts_motion_count shift_used_i=sts_shift_used}
  feature_detect_regs_if.regs r
);
  // register signals, joined to the interface r
  logic [32-1:0] ctrl_o;
  logic ctrl_wr_o;
  logic [32-1:0] frame_size_o;
  logic frame_size_wr_o;
  logic [32-1:0] edge_o;
  logic edge_wr_o;
  logic [32-1:0] motion_o;
  logic motion_wr_o;
  logic [32-1:0] shift_o;
  logic shift_wr_o;
  logic [32-1:0] shift_est_i;
  logic [32-1:0] status_i;
  logic [32-1:0] frames_i;
  logic [32-1:0] edge_count_i;
  logic [32-1:0] motion_count_i;
  logic [32-1:0] shift_used_i;
  assign r.cfg_ctrl = ctrl_o;
  assign r.cfg_ctrl_wr = ctrl_wr_o;
  assign r.cfg_frame_size = frame_size_o;
  assign r.cfg_frame_size_wr = frame_size_wr_o;
  assign r.cfg_edge = edge_o;
  assign r.cfg_edge_wr = edge_wr_o;
  assign r.cfg_motion = motion_o;
  assign r.cfg_motion_wr = motion_wr_o;
  assign r.cfg_shift = shift_o;
  assign r.cfg_shift_wr = shift_wr_o;
  assign shift_est_i = r.sts_shift_est;
  assign status_i = r.sts_status;
  assign frames_i = r.sts_frames;
  assign edge_count_i = r.sts_edge_count;
  assign motion_count_i = r.sts_motion_count;
  assign shift_used_i = r.sts_shift_used;
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "FEAT";
  localparam logic [31:0] IP_VERSION = "1.00";
  localparam logic [31:0] IP_DATE    = 32'h10142026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_CTRL = 8'h18;
  localparam logic [7:0] A_FRAME_SIZE = 8'h1C;
  localparam logic [7:0] A_EDGE = 8'h20;
  localparam logic [7:0] A_MOTION = 8'h24;
  localparam logic [7:0] A_SHIFT = 8'h28;
  localparam logic [7:0] A_SHIFT_EST = 8'h2C;
  localparam logic [7:0] A_STATUS = 8'h30;
  localparam logic [7:0] A_FRAMES = 8'h34;
  localparam logic [7:0] A_EDGE_COUNT = 8'h38;
  localparam logic [7:0] A_MOTION_COUNT = 8'h3C;
  localparam logic [7:0] A_SHIFT_USED = 8'h40;
  localparam int MAP_WORDS = 17;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  regbus_if #(.ADDR_W(8)) bus ();               // register bus of the AXI4-Lite front end
  assign wr_en = bus.wr;
  assign wr_addr = bus.waddr;
  assign wr_data = bus.wdata;
  assign wr_strb = bus.wstrb;
  assign rd_en = bus.rd;
  assign rd_addr = bus.raddr;
  assign bus.wr_err = wr_err_q;
  assign bus.rdata = rd_data;
  assign bus.rd_valid = 1'b1;
  assign bus.rd_err = 1'b0;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(clk),
    .aresetn(rst_n),
    .s_axil(s_axil),
    .bus(bus)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] ctrl_q;
  logic [31:0] frame_size_q;
  logic [31:0] edge_q;
  logic [31:0] motion_q;
  logic [31:0] shift_q;
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      ctrl_q <= 32'h0;
      ctrl_wr_o <= 1'b0;
      frame_size_q <= 32'h0;
      frame_size_wr_o <= 1'b0;
      edge_q <= 32'h80080;
      edge_wr_o <= 1'b0;
      motion_q <= 32'h2214;
      motion_wr_o <= 1'b0;
      shift_q <= 32'h0;
      shift_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || wa == A_SHIFT_EST || wa == A_STATUS || wa == A_FRAMES || wa == A_EDGE_COUNT || wa == A_MOTION_COUNT || wa == A_SHIFT_USED);   // writes to read-only words: SLVERR
      begin
        ctrl_wr_o <= wr_en && wa == A_CTRL;
        if (wr_en && wa == A_CTRL) ctrl_q <= (ctrl_q & ~wmask) | (wr_data & wmask);
      end
      begin
        frame_size_wr_o <= wr_en && wa == A_FRAME_SIZE;
        if (wr_en && wa == A_FRAME_SIZE) frame_size_q <= (frame_size_q & ~wmask) | (wr_data & wmask);
      end
      begin
        edge_wr_o <= wr_en && wa == A_EDGE;
        if (wr_en && wa == A_EDGE) edge_q <= (edge_q & ~wmask) | (wr_data & wmask);
      end
      begin
        motion_wr_o <= wr_en && wa == A_MOTION;
        if (wr_en && wa == A_MOTION) motion_q <= (motion_q & ~wmask) | (wr_data & wmask);
      end
      begin
        shift_wr_o <= wr_en && wa == A_SHIFT;
        if (wr_en && wa == A_SHIFT) shift_q <= (shift_q & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign ctrl_o = ctrl_q[32-1:0];
  assign frame_size_o = frame_size_q[32-1:0];
  assign edge_o = edge_q[32-1:0];
  assign motion_o = motion_q[32-1:0];
  assign shift_o = shift_q[32-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge clk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_CTRL: rd_data = ctrl_q;
      A_FRAME_SIZE: rd_data = frame_size_q;
      A_EDGE: rd_data = edge_q;
      A_MOTION: rd_data = motion_q;
      A_SHIFT: rd_data = shift_q;
      A_SHIFT_EST: rd_data = 32'(shift_est_i);
      A_STATUS: rd_data = 32'(status_i);
      A_FRAMES: rd_data = 32'(frames_i);
      A_EDGE_COUNT: rd_data = 32'(edge_count_i);
      A_MOTION_COUNT: rd_data = 32'(motion_count_i);
      A_SHIFT_USED: rd_data = 32'(shift_used_i);
      default: begin
      end
    endcase
  end
endmodule
